-- Private companion entrypoint generated by the local ROM importer.
return function(mod)
  local source = assert(mod:read("inventory.lua"))
  local loader = assert((loadstring or load)(source, "@bw-inventory"))
  local inventory = loader()
  mod.exports = mod.exports or {}
  mod.exports.sprite = function(folder, stem)
    local key = folder .. "/" .. stem
    local entry = inventory[key]
    if not entry then return nil end
    return entry
  end
  mod.exports.decodeSprite = function(folder, stem)
    if not inventory[folder .. "/" .. stem] then return nil end
    local path = assert(mod.assets:path("assets/" .. folder .. "/" .. stem .. ".png"))
    return love.image.newImageData(path)
  end
end
